STOCK_BODY_SHA = '3637a96c29305a0e3f7df19ecf96f85b77f98f0dbb0e783773d217ba2be6dde6'

def validate(spec, root):
    root=Path(root)
    require(root.is_absolute() and ".." not in root.parts, "private absolute namespace required")
    require(spec.get("package_versions")==PACKAGE_VERSIONS and len(PACKAGE_VERSIONS)==48, "exact reviewed48 package versions required")
    require(spec.get("expected_stock_body_sha256")==STOCK_BODY_SHA and spec.get("fixedpoint_helper")=={"path":str(root/"science/fixedpoint_helper.R"),"sha256":FIXEDPOINT_SHA}, "exact helper path/hash and stock body required")
    require(spec.get("library")==str(root/"code/R_HOME/library") and spec.get("R_HOME")==str(root/"code/R_HOME"), "installed library/native paths required")
    allowed={str(root/"code"/p):sha for p,sha in REQUIRED_PACKAGE_DLLS.items()}
    required={path:sha for path,sha in allowed.items() if Path(path).name in {'exdqlm.so','digest.so','jsonlite.so','Matrix.so','Rcpp.so','nimble.so'}}
    require(spec.get("allowed_package_DLLs")==allowed and spec.get("required_package_DLLs")==required,
            "exact reviewed actual-DLL allowlist and six mandatory namespace DLLs required")
    return True

